const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Great Lakes geometry (approximate polygon covering the five Great Lakes)
  var greatLakes = ee.Geometry.Polygon(
    [[[-92.5, 49.0],
      [-75.5, 49.0],
      [-75.5, 41.0],
      [-92.5, 41.0]]], null, false);

  // 2. Define date: February 11, 2016
  var startDate = '2016-02-11';
  var endDate = '2016-02-12'; // Exclusive end date

  // Function to extract cloud mask from MOD35_L2
  function getCloudMask(image) {
    // Extract cloud mask band (48-bit Cloud_Mask)
    var cloudMask = image.select('Cloud_Mask');
    // Get bit 0 (cloud mask flag: 0=confident clear, 1=probably cloudy or unknown)
    var cloudBit = cloudMask.rightShift(0).and(1);
    return cloudBit.rename('cloud');
  }

  // 3. Try MODIS Cloud Mask (MOD35_L2) first
  var modisCol = ee.ImageCollection('MODIS/006/MOD35_L2')
    .filterDate(startDate, endDate)
    .filterBounds(greatLakes);

  var collectionSize = modisCol.size().getInfo();
  console.log(`MODIS Cloud Mask images: ${collectionSize}`);

  // If empty, try MODIS Surface Reflectance (MOD09GA) as fallback
  if (collectionSize === 0) {
    console.log('No MODIS cloud mask found, trying MODIS surface reflectance...');
    var modisSR = ee.ImageCollection('MODIS/006/MOD09GA')
      .filterDate(startDate, endDate)
      .filterBounds(greatLakes);

    collectionSize = modisSR.size().getInfo();
    console.log(`MODIS Surface Reflectance images: ${collectionSize}`);

    if (collectionSize === 0) {
      console.log('<answer>C1</answer>');
      return;
    }

    // Use MOD09GA cloud state (bits 0-1 of state_1km band)
    var image = modisSR.first();
    var cloudState = image.select('state_1km').bitwiseAnd(3);
    // Cloud state: 00=clear, 01=cloudy, 10=mixed, 11=not set assumed clear
    // Consider 01 and 10 as cloudy
    var cloudMask = cloudState.gte(1).and(cloudState.lte(2));
    var cloudImage = cloudMask.rename('cloud');
  } else {
    // Use MOD35_L2 cloud mask
    var image = modisCol.first();
    var cloudImage = getCloudMask(image);
  }

  // 4. Count pixels with clouds and total valid pixels
  var cloudCount = cloudImage.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: greatLakes,
    scale: 1000,  // MODIS is 1km resolution
    maxPixels: 1e9
  }).get('cloud');

  var totalCount = cloudImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: greatLakes,
    scale: 1000,
    maxPixels: 1e9
  }).get('cloud');

  var cloudPixels = cloudCount.getInfo();
  var totalPixels = totalCount.getInfo();

  console.log(`Cloud pixels: ${cloudPixels}`);
  console.log(`Total valid pixels: ${totalPixels}`);

  // 5. Check for no valid pixels
  if (totalPixels === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // 6. Check for calculation failure
  if (cloudPixels === null || cloudPixels === undefined || 
      isNaN(cloudPixels) || totalPixels === null || 
      totalPixels === undefined || isNaN(totalPixels)) {
    console.log('<answer>C3</answer>');
    return;
  }

  // 7. Determine answer based on cloud presence
  var cloudPercentage = (cloudPixels / totalPixels) * 100;
  console.log(`Cloud coverage: ${cloudPercentage.toFixed(2)}%`);

  if (cloudPixels > 0) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
